import pathlib,json,gzip,hashlib
b=pathlib.Path('docs/review/fc77177/real_tool_closed_loop_sol_high_seven_triple_duty_batch_v1/input_bundle')
for f in ['r106_r107_complementary_branch_comparison_v1.md','r106_closeout_report_v1.json','r109_closeout_report_v1.json','revision_output_schema.json']:
 print('\\nFILE',f); print((b/f).read_text())
m=json.loads((b/'parent_identity_manifest_v1.json').read_text())
for r in [m['default_primary_parent']]+m['reference_parents']:
 p=b/r['relative_archive']; print('\\nARCHIVE',r['record_id']); print([str(f.relative_to(p)) for f in p.rglob('*') if f.is_file()])
 for f in p.rglob('*'):
  if f.name in ['plan_snapshot.json','action_snapshot.json','diagnostic_events.json.gz','diagnostic_events.json']:
   raw=f.read_bytes(); key={'plan_snapshot.json':'plan_sha256','action_snapshot.json':'action_sha256','diagnostic_events.json.gz':'events_gz_sha256','diagnostic_events.json':'events_restored_sha256'}[f.name]; print(f.name,hashlib.sha256(raw).hexdigest(), 'MATCH',hashlib.sha256(raw).hexdigest()==r[key])
   if f.name=='diagnostic_events.json.gz': print('restored MATCH',hashlib.sha256(gzip.decompress(raw)).hexdigest()==r['events_restored_sha256'])
   if f.name in ['plan_snapshot.json','action_snapshot.json']: print(raw.decode())
PY"

